interface IProgressToken { function mint(address to, uint256 amount) external returns (bool); }
function reward(address token, uint256 amount) external {
    require(token != address(0), "zero token");
    require(IProgressToken(token).mint(msg.sender, amount), "mint failed");
}

pragma solidity ^0.8.20;
interface IERC20Like { function transfer(address to, uint256 value) external returns (bool); }
contract RewardRouter { address public immutable owner; IERC20Like public immutable token; constructor(address tokenAddress) { require(tokenAddress != address(0)); owner = msg.sender; token = IERC20Like(tokenAddress); } function distribute(address to, uint256 amount) external { require(msg.sender == owner, "not owner"); require(token.transfer(to, amount), "transfer failed"); } }
